update public.learning_paths
set
  title = 'Project Management',
  goal = 'Project Management',
  summary = 'Frame project management as the disciplined coordination of scope, time, cost, quality, risk, stakeholders, resources, and value delivery. Topics cover selection and strategic alignment, stakeholders and chartering, requirements and work breakdown, scheduling, cost and earned value, resources, risk, quality and benefits, communication and leadership, procurement, delivery approaches, monitoring and control, project information systems, ethics, and an integrated project plan.',
